     jest.spyOn(marpCli, 'default').mockRejectedValue(new Error('ERROR'))

     await exportModule.doExport(saveURI, document)
     expect(window.showErrorMessage).toHaveBeenCalledWith(
       expect.stringContaining('[Error] ERROR')
     )
   })
 })

